/* ===================== BÀI 30 · Ngắt ngoài và ngắt timer ===================== */
/* Bài 30 · Ngắt ngoài và ngắt timer (AMTS-EMB-001-M08-L02, MC51-030) — sinh bởi tools/author/mcu8051/l30.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR30=[{"label":"Ví dụ: Đếm lần bấm nút bằng INT0 kích sườn","code":"; Ví dụ 1: đếm lần bấm nút K1 bằng INT0 kích sườn\n; Chip: AT89S52, 12 MHz. K1 nối P3.2: bấm = chân xuống 0.\n; Main chờ 512 chu kỳ máy rồi dừng; bấm K1 trong lúc chờ.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     0003H                   ; vectơ INT0\n        INC     30H                     ; ISR: đếm một lần bấm\n        RETI\n        ORG     0030H\nMAIN:   MOV     30H,#0\n        SETB    IT0                     ; IT0 = 1: kích sườn xuống\n        SETB    EX0\n        SETB    EA\n        MOV     R7,#0                   ; 256 vòng × 2 chu kỳ\nCHO:    DJNZ    R7,CHO\n        CLR     EA\n        SJMP    $\n        END\n","note":"Bấm Chạy rồi bấm K1 vài lần (mỗi lần là một sườn xuống). Kịch bản kiểm chứng: K1 bấm ở chu kỳ 100–160 và 300–360 → vào ISR đúng 2 lần (chu kỳ 102 và 303), 30H = 02H, tổng 531 chu kỳ. Giữ nút lâu hơn cũng chỉ đếm 1.","dev":{"led":true,"btn":true},"fosc":12000000},{"label":"Lỗi: Kích mức, giữ nút 300 µs","code":"; Ví dụ 2 (LỖI): INT0 kích mức, giữ nút 300 µs\n; Quên SETB IT0: sau reset IT0 = 0 (kích mức). Chừng nào\n; chân còn 0, ISR chạy lại ngay sau mỗi RETI.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     0003H\n        INC     30H                     ; đếm số lần vào ISR\n        RETI\n        ORG     0030H\nMAIN:   MOV     30H,#0\n        SETB    EX0                     ; quên SETB IT0\n        SETB    EA\n        MOV     R7,#0\nCHO:    DJNZ    R7,CHO\n        CLR     EA\n        SJMP    $\n        END\n","note":"Bấm Chạy, giữ K1 (đánh dấu Giữ nút) một lúc rồi nhả. Kịch bản kiểm chứng: chân P3.2 = 0 từ chu kỳ 101 tới 400 → 30H = 2BH (43 lần vào ISR cho MỘT lần bấm). Sửa: thêm SETB IT0 trước SETB EX0.","dev":{"led":true,"btn":true},"fosc":12000000},{"label":"Ví dụ: Tick 100 µs, Timer 0 chế độ 2","code":"; Ví dụ 3: tick 100 µs bằng Timer 0 chế độ 2 (tự nạp)\n; TH0 = 256 - 100 = 9CH: tràn đúng mỗi 100 chu kỳ máy.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH                   ; vectơ Timer 0\n        CPL     P1.0                    ; ISR: đảo LED P1.0\n        INC     30H                     ; đếm tick\n        RETI                            ; TF0 đã tự xóa khi vào ngắt\n        ORG     0030H\nMAIN:   MOV     30H,#0\n        MOV     TMOD,#02H               ; Timer 0 chế độ 2\n        MOV     TH0,#9CH                ; giá trị tự nạp\n        MOV     TL0,#9CH                ; lần tràn đầu cũng sau 100\n        MOV     IE,#82H                 ; EA + ET0\n        SETB    TR0\nCHO:    MOV     A,30H\n        CJNE    A,#5,CHO                ; chờ đủ 5 tick\n        CLR     TR0\n        CLR     EA\n        SJMP    $\n        END\n","note":"Xem phần Thời gian: cờ TF0 bật đều ở 113, 213, 313, 413, 513 (chế độ 2 tự nạp). Đoán trước: LED P1.0 có đổi mức đúng mỗi 100 chu kỳ không? Không hẳn: 99, 100, 101, 99 vì ISR phải chờ lệnh main đang chạy xong. Tổng 525 chu kỳ, 30H = 05H.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Tick 0,5 ms, nạp lại trong ISR (trôi)","code":"; Ví dụ 4: tick 0,5 ms bằng Timer 0 chế độ 1, nạp lại\n; trong ISR. 65536 - 500 = 65036 = FE0CH. Đo khoảng\n; cách giữa hai lần tràn: dài hơn 500 chu kỳ!\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        MOV     TH0,#0FEH               ; nạp lại: timer đã đếm tiếp\n        MOV     TL0,#0CH                ; từ 0000H trong lúc chờ\n        CPL     P1.0\n        INC     30H\n        RETI\n        ORG     0030H\nMAIN:   MOV     30H,#0\n        MOV     TMOD,#01H               ; Timer 0 chế độ 1 (16 bit)\n        MOV     TH0,#0FEH\n        MOV     TL0,#0CH\n        MOV     IE,#82H\n        SETB    TR0\nCHO:    MOV     A,30H\n        CJNE    A,#3,CHO                ; chờ 3 tick\n        CLR     TR0\n        CLR     EA\n        SJMP    $\n        END\n","note":"Cờ TF0 bật ở 513, 1019, 1525: tick dài 506 thay vì 500 chu kỳ. ISR ghi đè TH0, TL0 bằng FE0CH sau khi timer đã đếm tiếp từ 0000H được 6–7 chu kỳ, số đó bị mất ở mỗi tick.","dev":{"led":true},"fosc":12000000},{"label":"Sửa: Nạp lại có bù, đúng 500 chu kỳ","code":"; Ví dụ 5 (SỬA): nạp lại có bù, tick đúng 500 chu kỳ\n; Cộng giá trị nạp VÀO số timer đã đếm từ lúc tràn,\n; cộng thêm 7 chu kỳ timer bị dừng trong lúc cộng.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        LJMP    T0ISR\n        ORG     0030H\nMAIN:   MOV     30H,#0\n        MOV     TMOD,#01H\n        MOV     TH0,#0FEH\n        MOV     TL0,#0CH\n        MOV     IE,#82H\n        SETB    TR0\nCHO:    MOV     A,30H\n        CJNE    A,#3,CHO\n        CLR     TR0\n        CLR     EA\n        SJMP    $\nT0ISR:  PUSH    ACC\n        PUSH    PSW\n        CLR     TR0                     ; dừng timer 7 chu kỳ\n        MOV     A,TL0                   ; số đã đếm sau khi tràn\n        ADD     A,#13H                  ; 0CH + 7\n        MOV     TL0,A\n        MOV     A,TH0\n        ADDC    A,#0FEH\n        MOV     TH0,A\n        SETB    TR0\n        CPL     P1.0\n        INC     30H\n        POP     PSW\n        POP     ACC\n        RETI\n        END\n","note":"Cùng chương trình, ISR cộng giá trị nạp vào số đang có và bù 7 chu kỳ dừng timer: cờ TF0 ở 513, 1013, 1513, đúng 500 chu kỳ. Lần vào ngắt đầu ở 514, sau đó 1015, 1514: độ rung 1 chu kỳ, không trôi.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Lần bấm cũ trước khi bật ngắt","code":"; Ví dụ 6 (BẪY): lần bấm cũ trước khi bật ngắt\n; K1 được bấm lúc khởi động (EA còn 0). Cờ IE0 kích sườn\n; nhớ lần bấm đó: vừa SETB EA là vào ISR ngay.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     0003H\n        INC     30H\n        RETI\n        ORG     0030H\nMAIN:   MOV     30H,#0\n        SETB    IT0\n        SETB    EX0\n        MOV     R7,#50                  ; khởi động khác: 100 chu kỳ\nTRE:    DJNZ    R7,TRE\n; CLR IE0           ; sửa: xóa sự kiện cũ ở đây\n        SETB    EA\n        MOV     R7,#100                 ; chờ 200 chu kỳ, không bấm\nCHO:    DJNZ    R7,CHO\n        CLR     EA\n        SJMP    $\n        END\n","note":"K1 được bấm lúc khởi động (chu kỳ 20–60), khi EA = 0. IE0 kích sườn nhớ lần bấm đó: ngay sau SETB EA (và một lệnh nữa) CPU vào ISR ở chu kỳ 109 dù không ai bấm nữa: 30H = 01H. Bỏ dấu ; trước CLR IE0 rồi chạy lại để thấy 30H = 00H.","dev":{"led":true,"btn":true},"fosc":12000000}];
const sim30=makeSim51(document.getElementById("m51-l30"),{id:"s30",presets:PR30,ram:256});
makeEx51(document.getElementById("ex-l30"),"l30",[{"t":"Tick 100 µs bằng Timer 0 chế độ 2","d":"<p>ISR Timer 0 trong code mẫu đảo LED <code>P1.0<\/code> và tăng bộ đếm tick <code>40H<\/code>. Phần dưới của MAIN (giữ nguyên) chạy Timer 1 làm <b>cửa sổ đo<\/b>: Timer 1 và Timer 0 bắt đầu cùng một chu kỳ máy (<code>MOV TCON,#50H<\/code>), Timer 1 tràn sau <i>W<\/i> = 65536 − (<code>30H<\/code>:<code>31H<\/code>) chu kỳ thì main tắt ngắt và dừng. Hãy sửa phần cấu hình để Timer 0 tạo tick đúng <b>100 µs<\/b> ở 12 MHz bằng chế độ 2 (tự nạp), tick đầu tiên cũng sau đúng 100 µs. Timer 1 vẫn ở chế độ 1.<\/p><p>Kết quả: <code>40H<\/code> = số tick trong cửa sổ, <code>P1.0<\/code> đã đảo bấy nhiêu lần, <code>TH0 = 9CH<\/code>.<\/p><p>Ví dụ: <code>30H:31H = FBH:E6H<\/code> (<i>W<\/i> = 65536 − 64486 = 1050 chu kỳ) → <code>40H = 0AH<\/code>, <code>P1 = FFH<\/code>.<\/p>","start":"; Bài 1: tick 100 µs bằng Timer 0 chế độ 2 (tự nạp)\n; Timer 1 đo một cửa sổ thời gian cố định; 40H = số tick\n; trong cửa sổ. Code mẫu chạy được nhưng Timer 0 sai chế độ.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        CPL     P1.0                    ; ISR: đảo LED, đếm tick\n        INC     40H\n        RETI\n        ORG     0030H\nMAIN:   MOV     40H,#0\n; ---- sửa phần này: chế độ Timer 0, giá trị nạp ----\n        MOV     TMOD,#11H               ; T1: chế độ 1; T0: ??? (sai)\n; ---- phần dưới giữ nguyên ----\n        MOV     TH1,30H                 ; cửa sổ = 65536 - (30H:31H)\n        MOV     TL1,31H\n        MOV     IE,#82H                 ; EA + ET0\n        MOV     TCON,#50H               ; TR1 = TR0 = 1 cùng lúc\n        JNB     TF1,$                   ; chờ hết cửa sổ\n        CLR     EA\n        CLR     TR0\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":251,"0x31":230}},"expect":{"iram":{"0x40":10},"ports":{"P1":255},"regs":{"TH0":156}}},{"setup":{"iram":{"0x30":255,"0x31":206}},"expect":{"iram":{"0x40":0},"ports":{"P1":255},"regs":{"TH0":156}}},{"setup":{"iram":{"0x30":255,"0x31":106}},"expect":{"iram":{"0x40":1},"ports":{"P1":254},"regs":{"TH0":156}}},{"setup":{"iram":{"0x30":241,"0x31":110}},"expect":{"iram":{"0x40":37},"ports":{"P1":254},"regs":{"TH0":156}}},{"setup":{"iram":{"0x30":216,"0x31":170}},"expect":{"iram":{"0x40":100},"ports":{"P1":255},"regs":{"TH0":156}}},{"setup":{"iram":{"0x30":156,"0x31":50}},"expect":{"iram":{"0x40":255},"ports":{"P1":254},"regs":{"TH0":156}}}]},"hints":["Chạy code mẫu: TMOD = 11H đặt Timer 0 ở chế độ 1 (16 bit, đếm từ 0000H) nên tick đầu tiên tới sau 65536 chu kỳ, cửa sổ đã hết từ lâu.","TMOD: nửa cao cho Timer 1 (giữ chế độ 1 = 1H), nửa thấp cho Timer 0 (chế độ 2 = 2H) → 12H. Chế độ 2 tràn khi TL0 đi từ FFH về 00H rồi nạp TL0 = TH0.","Giá trị nạp cho chế độ 2 là 256 − số nhịp; nạp cả TL0 để lần tràn đầu cũng đúng."],"why":"Chế độ 2 tự nạp TL0 từ TH0 ngay trong chu kỳ tràn, phần cứng làm, không phụ thuộc lúc nào ISR chạy: tick đều đúng 100 chu kỳ máy bất kể độ trễ vào ngắt. Giá trị nạp = 256 − số lần đếm. Quên nạp TL0 thì tick đầu tiên dài 256 − 0 = 256 chu kỳ."},{"t":"Một lần bấm, một lần đếm","d":"<p>ISR INT0 tăng <code>40H<\/code>, ISR INT1 tăng <code>41H<\/code>. Phần dưới của MAIN (giữ nguyên) giả lập người dùng: kéo chân <code>P3.2<\/code> (nút K1) xuống 0 rồi nhả, lặp <code>[30H]<\/code> lần; rồi tương tự với <code>P3.3<\/code> (K2) <code>[31H]<\/code> lần; mỗi lần giữ khoảng 20 chu kỳ máy. Khi chương trình dừng ở <code>SJMP $<\/code>, <code>40H<\/code> phải bằng đúng số lần bấm K1 và <code>41H<\/code> bằng số lần bấm K2. Hãy sửa phần cấu hình ngắt ngoài.<\/p><p>Ví dụ: <code>30H = 2<\/code>, <code>31H = 1<\/code> → <code>40H = 02H<\/code>, <code>41H = 01H<\/code>.<\/p>","start":"; Bài 2: đếm lần bấm K1 (INT0, P3.2) vào 40H và K2\n; (INT1, P3.3) vào 41H. Phần giả lập bấm nút giữ nguyên:\n; K1 bấm [30H] lần, K2 bấm [31H] lần, mỗi lần giữ ~20 µs.\n; Code mẫu đếm sai: một lần bấm thành nhiều lần.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     0003H\n        INC     40H\n        RETI\n        ORG     0013H\n        INC     41H\n        RETI\n        ORG     0030H\nMAIN:   MOV     40H,#0\n        MOV     41H,#0\n; ---- sửa phần cấu hình ngắt ngoài ----\n        MOV     IE,#85H                 ; EA + EX1 + EX0\n; ---- phần dưới giữ nguyên ----\n        MOV     A,30H\n        JZ      XK2\n        MOV     R6,A\nLK1:    CLR     P3.2                    ; bấm K1 (kéo chân xuống 0)\n        MOV     R7,#10\n        DJNZ    R7,$                    ; giữ ~20 chu kỳ\n        SETB    P3.2                    ; nhả\n        MOV     R7,#10\n        DJNZ    R7,$\n        DJNZ    R6,LK1\nXK2:    MOV     A,31H\n        JZ      XONG\n        MOV     R6,A\nLK2:    CLR     P3.3                    ; bấm K2\n        MOV     R7,#10\n        DJNZ    R7,$\n        SETB    P3.3\n        MOV     R7,#10\n        DJNZ    R7,$\n        DJNZ    R6,LK2\nXONG:   CLR     EA\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":2,"0x31":1}},"expect":{"iram":{"0x40":2,"0x41":1},"ports":{"P3":255}}},{"setup":{"iram":{"0x30":0,"0x31":0}},"expect":{"iram":{"0x40":0,"0x41":0},"ports":{"P3":255}}},{"setup":{"iram":{"0x30":1,"0x31":0}},"expect":{"iram":{"0x40":1,"0x41":0},"ports":{"P3":255}}},{"setup":{"iram":{"0x30":0,"0x31":3}},"expect":{"iram":{"0x40":0,"0x41":3},"ports":{"P3":255}}},{"setup":{"iram":{"0x30":5,"0x31":5}},"expect":{"iram":{"0x40":5,"0x41":5},"ports":{"P3":255}}},{"setup":{"iram":{"0x30":9,"0x31":2}},"expect":{"iram":{"0x40":9,"0x41":2},"ports":{"P3":255}}}]},"hints":["Chạy code mẫu từng bước và để ý phần Thời gian: trong lúc chân P3.2 còn ở 0, cờ IE0 bật lại ngay sau mỗi RETI.","Sau reset IT0 = IT1 = 0: kích mức. Kích mức gọi ISR liên tục chừng nào chân còn 0. Một lần bấm chỉ có một sườn xuống.","Chuyển hai ngắt ngoài sang kích sườn bằng các bit IT trong TCON, trước khi cho phép ngắt."],"why":"Kích sườn (ITx = 1): phần cứng bật IEx khi thấy chân 1 ở lần lấy mẫu trước và 0 ở lần sau, rồi tự xóa IEx khi vào ngắt, nên mỗi lần bấm đúng một lần ISR dù giữ nút lâu. Kích mức hợp với nguồn ngắt giữ chân ở 0 cho tới khi được phục vụ (ví dụ chip ngoại vi), không hợp với nút bấm. Test 30H = 31H = 0 là trường hợp biên."},{"t":"Tick 1 ms không trôi","d":"<p>MAIN (giữ nguyên) chạy Timer 0 chế độ 1 với giá trị đầu FC18H (tràn sau 1000 chu kỳ) và Timer 1 làm cửa sổ đo như bài 1: <i>W<\/i> = 65536 − (<code>30H<\/code>:<code>31H<\/code>) chu kỳ, lớn nhất khoảng 64 tick. ISR của code mẫu nạp lại TH0, TL0 bằng hằng số nên mỗi tick dài hơn 1000 chu kỳ và trôi dần. Hãy viết lại <b>chỉ ISR<\/b> <code>T0ISR<\/code> để mọi tick dài <b>đúng 1000 chu kỳ máy<\/b> (sai 1 chu kỳ cũng bị phát hiện ở cửa sổ 60 tick) và <code>40H<\/code> = số tick trong cửa sổ.<\/p><p>Ví dụ: <code>30H:31H = F2H:54H<\/code> (<i>W<\/i> = 65536 − 62036 = 3500 chu kỳ) → <code>40H = 03H<\/code>.<\/p>","start":"; Bài 3: tick 1 ms không trôi, Timer 0 chế độ 1\n; Timer 1 đo cửa sổ cố định; 40H = số tick trong cửa sổ.\n; Code mẫu nạp lại muộn trong ISR nên mỗi tick dài hơn\n; 1000 chu kỳ: sau vài chục tick là mất một tick.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        LJMP    T0ISR\n        ORG     0030H\nMAIN:   MOV     40H,#0                  ; ---- MAIN giữ nguyên ----\n        MOV     TMOD,#11H               ; T1, T0: chế độ 1 (16 bit)\n        MOV     TH0,#0FCH               ; 65536 - 1000 = FC18H\n        MOV     TL0,#18H\n        MOV     TH1,30H                 ; cửa sổ = 65536 - (30H:31H)\n        MOV     TL1,31H\n        MOV     IE,#82H\n        MOV     TCON,#50H               ; TR1 = TR0 = 1 cùng lúc\n        JNB     TF1,$\n        CLR     EA\n        CLR     TR0\n        SJMP    $\n; ---- chỉ sửa ISR ----\nT0ISR:  MOV     TH0,#0FCH               ; nạp lại muộn: timer đã đếm\n        MOV     TL0,#18H                ; tiếp từ 0000H, bị ghi đè\n        INC     40H\n        RETI\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":242,"0x31":84}},"expect":{"iram":{"0x40":3}}},{"setup":{"iram":{"0x30":177,"0x31":124}},"expect":{"iram":{"0x40":20}}},{"setup":{"iram":{"0x30":21,"0x31":110}},"expect":{"iram":{"0x40":60}}},{"setup":{"iram":{"0x30":17,"0x31":234}},"expect":{"iram":{"0x40":60}}},{"setup":{"iram":{"0x30":96,"0x31":60}},"expect":{"iram":{"0x40":40}}},{"setup":{"iram":{"0x30":4,"0x31":212}},"expect":{"iram":{"0x40":64}}}]},"hints":["Lúc ISR chạy, Timer 0 đã đếm tiếp từ 0000H được vài chu kỳ (độ trễ vào ngắt + LJMP), và số đó thay đổi theo lệnh main đang chạy. Ghi đè bằng hằng số là bỏ mất số đó.","Cộng giá trị nạp VÀO số đang có: TL0 = TL0 + 18H, TH0 = TH0 + FCH + nhớ. Dừng Timer 0 (CLR TR0) trong lúc cộng để TL0 không đổi giữa chừng.","Trong lúc dừng để cộng, timer bỏ lỡ vài chu kỳ: bù đúng số chu kỳ đó vào giá trị cộng. ISR dùng A và ADD thì phải giữ những gì?"],"why":"Chế độ 1 không tự nạp: ISR phải nạp lại, và lúc đó timer đã đếm được một số chu kỳ thay đổi theo độ trễ vào ngắt. Cộng giá trị nạp vào số đang đếm (thay vì ghi đè) giữ nguyên phần đã đếm; bù thêm đúng số chu kỳ timer bị dừng thì chu kỳ tick đúng 1000. Cửa sổ 60 tick với lề 50 chu kỳ phát hiện tick 1001 hoặc 999 chu kỳ."}]);

makeQuiz("quiz30","score30",[{"q": "INT0 để ở chế độ mặc định sau reset (IT0 = 0). Nút nối P3.2 được giữ ở mức 0 trong 1 ms. Điều gì xảy ra?", "o": ["ISR chạy đúng 1 lần ở sườn xuống", "ISR chạy 1 lần ở sườn lên khi nhả nút", "ISR INT0 chạy lặp lại nhiều lần trong lúc nút còn được giữ", "ISR không chạy vì cờ IE0 chỉ bật ở chế độ sườn"], "a": 2, "e": "IT0 = 0 là kích mức: IE0 đi theo mức chân, vào ngắt không xóa được yêu cầu, nên sau mỗi RETI (và một lệnh main) CPU vào ISR lại chừng nào chân còn 0 (ví dụ 2: 43 lần trong 300 µs)."}, {"q": "Cờ nào KHÔNG được phần cứng tự xóa khi CPU vào ISR tương ứng?", "o": ["TF0", "TF1", "RI (cổng nối tiếp)", "IE1 khi IT1 = 1"], "a": 2, "e": "TF0, TF1 và IE0/IE1 ở chế độ sườn được xóa khi phần cứng gọi ngắt. RI, TI (và TF2, EXF2) không tự xóa vì ISR cần đọc chúng để biết nguồn nào gọi; ISR phải xóa bằng lệnh."}, {"q": "Cần tick 200 µs ở 12 MHz bằng Timer 0 chế độ 2. Giá trị TH0 là bao nhiêu?", "o": ["C8H", "FF38H", "37H", "38H"], "a": 3, "e": "Chế độ 2 tràn sau 256 − TH0 lần đếm, mỗi lần 1 µs ở 12 MHz: TH0 = 256 − 200 = 56 = 38H. C8H = 200 là nhầm số lần đếm với giá trị nạp; FF38H là giá trị 16 bit của chế độ 1."}, {"q": "ISR Timer 0 (chế độ 1) ghi lại TH0, TL0 bằng hằng số ở đầu ISR. Tick đo được dài hơn tính toán vài chu kỳ. Nguyên nhân?", "o": ["Thạch anh 12 MHz bị sai số", "Timer đã đếm tiếp từ 0000H trong lúc chờ vào ngắt; ghi đè làm mất số đó", "Lệnh RETI chạy chậm hơn RET", "TF0 không tự xóa nên ISR chạy hai lần"], "a": 1, "e": "Sau khi tràn, timer chế độ 1 tiếp tục đếm từ 0000H trong suốt độ trễ vào ngắt và các lệnh đầu ISR. Ghi đè bằng hằng số bỏ mất các lần đếm đó, nên mỗi tick dài thêm chừng ấy (ví dụ 4: 506 thay vì 500). Sửa: cộng giá trị nạp vào số đang có."}, {"q": "Cờ TF0 bật đều đặn mỗi 100 chu kỳ, nhưng LED được đảo trong ISR đổi mức cách nhau 99, 100, 101 chu kỳ. Hiện tượng này là gì?", "o": ["Độ rung: thời điểm ISR chạy phụ thuộc lệnh main đang chạy, không cộng dồn", "Độ trôi: chu kỳ timer sai và cộng dồn", "Lỗi của trình mô phỏng", "Mất ngắt vì cờ TF0 bị ghi đè"], "a": 0, "e": "CPU chỉ vào ngắt khi lệnh đang chạy kết thúc, nên thời điểm ISR lệch 0–1 chu kỳ tùy lệnh (1 hay 2 chu kỳ). Trung bình vẫn đúng 100: đó là độ rung, không phải độ trôi (ví dụ 3)."}]);

